    prior,doc,names=map(read,[PRIOR,DOC,NAMES]);data={k:read(p) for k,p in PROOFS.items()}
    assert prior['completed']==7082 and prior['manifest_batches']==637
    assert sha(Path(prior['candidate']).read_bytes())==prior['candidate_sha256']==doc['current_ROM_sha256']
    assert sha(Path(prior['patch']).read_bytes())==prior['patch_sha256']
    assert len(doc['records'])==61 and doc['revised']==31 and doc['retained']==30 and all(all(r['review'].values()) for r in doc['records'])
    assert len(names['records'])==7 and all(all(r['review'].values()) for r in names['records'])
    approval=data['actual_approval'];policy=data['native_policy_validation'];seal=data['reference_seal']
    assert approval['actual_complete_holds']==318 and approval['actual_speech_occurrences']==100
    assert len(approval['directly_viewed_sheets'])==22 and all(s['directly_viewed'] and sha(Path(s['path']).read_bytes())==s['sha256'] for s in approval['directly_viewed_sheets'])
    assert policy['positive_count']==61 and policy['negative_count']==1014
    assert not data['actual_proof']['unresolved'] and data['actual_proof']['actual_total_frames']==48002
    assert seal['manuscript_sha256']==sha(DOC.read_bytes()) and seal['reference_map_sha256']==sha(Path(PROOFS['sealed_map']).read_bytes())
    assert sha(Path(seal['research_ROM']).read_bytes())==seal['research_ROM_sha256']
    return prior,doc,names,data

